IPC::PlatformFileForTransit DuplicatePlatformFileForProcess(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
  HANDLE dup_handle = NULL;
  if (!DuplicateHandle(GetCurrentProcess(), handle, process, &dup_handle, 0, FALSE,
                       close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
    return base::kInvalidPlatformFileForTransit;
  }
  return IPC::PlatformFileForTransit(dup_handle);
#else
  int flags = close_source_handle ? FD_CLOEXEC : 0;
  int dup_fd = fcntl(handle, F_DUPFD_CLOEXEC, 0);
  if (dup_fd == -1) {
    return base::kInvalidPlatformFileForTransit;
  }

  // Set the close-on-exec flag if required.
  if (flags & FD_CLOEXEC) {
    fcntl(dup_fd, F_SETFD, FD_CLOEXEC);
  }

  return IPC::PlatformFileForTransit(dup_fd);
#endif
}

#include "base/process.h"
#include "ipc/ipc_platform_file.h"
#include "base/file_util.h"

IPC::PlatformFileForTransit DuplicatePlatformFileForProcess(
    base::PlatformFile handle,
    base::ProcessHandle process,
    bool close_source_handle) {
#if defined(OS_WIN)
    base::PlatformFile duplicated_handle = base::kInvalidPlatformFileValue;
    if (DuplicateHandle(
            GetCurrentProcess(), handle, reinterpret_cast<HANDLE*>(&duplicated_handle),
            0, 0, FALSE, close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
        return IPC::PlatformFileForTransit(duplicated_handle);
    }
    return IPC::PlatformFileForTransit();
#else
    base::PlatformFile duplicated_handle = handle;
    if (close_source_handle) {
        base::PlatformFile new_handle = dup(handle);
        if (new_handle != base::kInvalidPlatformFileValue) {
            duplicated_handle = new_handle;
        }
    }
    return IPC::PlatformFileForTransit(duplicated_handle);
#endif
}

