IPC::PlatformFileForTransit DuplicatePlatformFileForProcess(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
    HANDLE target_handle;
    if (!DuplicateHandle(GetCurrentProcess(), handle, process, &target_handle, 0, FALSE,
                         close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
        return IPC::InvalidPlatformFileForTransit();
    }
    return IPC::PlatformFileForTransit(target_handle);
#else
    int flags = close_source_handle ? O_CLOEXEC : 0;
    int dup_handle = fcntl(handle, F_DUPFD_CLOEXEC, 0);
    if (dup_handle == -1) {
        return IPC::InvalidPlatformFileForTransit();
    }

    // Set close-on-exec flag to ensure handle is closed when sent to another process.
    if (flags & O_CLOEXEC) {
        fcntl(dup_handle, F_SETFD, FD_CLOEXEC);
    }

    return IPC::PlatformFileForTransit(dup_handle);
#endif
}

#include "base/process.h"
#include "base/platform_file.h"
#include "ipc/ipc_message_utils.h"

IPC::PlatformFileForTransit DuplicatePlatformFileHandle(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
    HANDLE target_handle;
    if (!DuplicateHandle(GetCurrentProcess(), handle, process, &target_handle, 0, FALSE, close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
        return IPC::InvalidPlatformFileForTransit();
    }
    return IPC::PlatformFileForTransit(target_handle);
#else
    base::subtle::PlatformFileNoClose fd = handle;
    if (fd == base::kInvalidPlatformFileValue) {
        return IPC::InvalidPlatformFileForTransit();
    }

    if (close_source_handle) {
        // POSIX: When close_source_handle is true, we can close the source after duplication.
        int flags = fcntl(fd, F_GETFD);
        if (flags == -1 || fcntl(fd, F_SETFD, flags | FD_CLOEXEC) == -1) {
            return IPC::InvalidPlatformFileForTransit();
        }
    }

    // On POSIX, no need to close the source handle immediately if it's not required.
    // The duplicated fd will be valid until sent or closed explicitly.
    return IPC::PlatformFileForTransit(fd);
#endif
}

#include <windows.h>

IPC::PlatformFileForTransit DuplicatePlatformFile(
    base::PlatformFile handle,
    base::ProcessHandle process,
    bool close_source_handle) {
  IPC::PlatformFileForTransit result = IPC::InvalidPlatformFileForTransit();

  // Windows-specific logic
  HANDLE duplicate_handle = NULL;
  if (DuplicateHandle(
          GetCurrentProcess(), handle, process, &duplicate_handle, 0, FALSE,
          close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
    result = IPC::PlatformFileForTransit(duplicate_handle);
  }

  return result;
}
